  g.links.forEach((l,i)=>{const x=l.sourceNode.x+8,xx=l.targetNode.x;const c=(xx-x)*curve;const d=`M ${x} ${l.sy} C ${x+c} ${l.sy} ${xx-c} ${l.ty} ${xx} ${l.ty} L ${xx} ${l.ty+l.width} C ${xx-c} ${l.ty+l.width} ${x+c} ${l.sy+l.width} ${x} ${l.sy+l.width} Z`;interactive(make('path',{d,fill:pattern(i),stroke:color,'stroke-width':strokeWidth}),l.id,{label:`${l.sourceNode.label} → ${l.targetNode.label}`,value:l.value,denominator:l.sourceNode.value,total:g.total,source:l.source,target:l.target,kind:'link'});});
  g.nodes.forEach(n=>{svg.append(make('rect',{x:n.x,y:n.y,width:8,height:n.height,fill:color}));if(labels){svg.append(text(n.x,n.y-25,n.label,14,{'text-anchor':n.level===depth?'end':'start'}));svg.append(text(n.x,n.y-7,fmt(n.value),12,{'text-anchor':n.level===depth?'end':'start'}));}});svg.atlasLayout=g;
